CREATE TABLE payment_attempts (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), idempotency_key TEXT NOT NULL UNIQUE, card_token TEXT NOT NULL, amount_cents BIGINT NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'USD', state TEXT NOT NULL DEFAULT 'pending', psp_reference_id TEXT, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (state IN ('pending','succeeded','failed')));
